import SwiftUI

/// The rows of a relation on a form: those loaded with the record, and those added on it.
public struct RowsState: Sendable, Equatable {
    public var loaded: [Fields]
    public var added: [Values]

    public init(loaded: [Fields] = [], added: [Values] = []) {
        self.loaded = loaded
        self.added = added
    }
}

/// The rows of a relation under a form, as data: what they start as, what
/// stops them being sent, and what is sent.
public enum Rows {
    /// An added row with no value typed yet.
    public static func emptyRow(_ rows: ChildRowsSchema) -> Values {
        Values(uniqueKeysWithValues: rows.fields.map { ($0.name, $0.type == .checkbox ? "false" : "") })
    }

    /// The rows a form starts with: the loaded ones, and as many empty rows as the request needs.
    public static func startRows(_ rows: ChildRowsSchema, _ record: Fields) -> RowsState {
        let loaded = rows.loaded.flatMap { record[$0]?.items }?.compactMap { item -> Fields? in
            if case .object(let members) = item { return members }
            return nil
        } ?? []
        let room = rows.maximum.map { $0 - loaded.count } ?? Int.max
        let count = max(0, min(rows.minimum ?? 0, room))
        return RowsState(loaded: loaded, added: (0..<count).map { _ in emptyRow(rows) })
    }

    /// The key under which the problem of an added row's field is held.
    public static func rowKey(_ rows: ChildRowsSchema, _ index: Int, _ field: String) -> String {
        rows.name + "." + String(index) + "." + field
    }

    /// What stops the rows being sent: too few rows added, more rows than the
    /// maximum, under the rows' name, and each added row's fields by their
    /// keywords, under the row's key.
    public static func rowProblems(_ rows: ChildRowsSchema, _ state: RowsState, _ texts: Texts) -> [String: String] {
        var problems: [String: String] = [:]
        if let minimum = rows.minimum, state.added.count < minimum {
            problems[rows.name] = say(texts, Message(text: "screens.rowsAtLeast", count: Double(minimum)))
        }
        if let maximum = rows.maximum, state.loaded.count + state.added.count > maximum {
            problems[rows.name] = say(texts, Message(text: "screens.rowsAtMost", count: Double(maximum)))
        }
        for (index, values) in state.added.enumerated() {
            for (field, problem) in Rules.formProblems(rows.fields, [], values, [:], texts) {
                problems[rowKey(rows, index, field)] = problem
            }
        }
        return problems
    }

    /// The rows as the request's body takes them: each added row with the fields its items take.
    public static func rowsSent(_ rows: ChildRowsSchema, _ state: RowsState) -> JSON {
        .array(state.added.map { values in
            var row: [String: JSON] = [:]
            for field in rows.fields where rows.sent.contains(field.name) {
                let value = Rules.typed(field, values[field.name] ?? "")
                if value != .null {
                    row[field.name] = value
                }
            }
            return .object(row)
        })
    }

    /// A value as a cell shows it: none when it is empty, yes or no for a boolean.
    public static func shown(_ value: JSON?, _ texts: Texts) -> String {
        switch value {
        case nil, .null?, .string("")?:
            return say(texts, "screens.none")
        case .bool(let b)?:
            return say(texts, b ? "screens.yes" : "screens.no")
        case let v?:
            return v.text
        }
    }
}

/// The rows of a relation under a form: the loaded rows read-only, and the
/// rows added on the form, each drawn inline by its fields' parts with a
/// button that removes it, up to the maximum. A field the request does
/// not take is shown on the loaded rows only.
public struct ChildRows: View {
    let rows: ChildRowsSchema
    @Binding var state: RowsState
    let problems: [String: String]
    let texts: Texts

    var full: Bool { rows.maximum.map { state.loaded.count + state.added.count >= $0 } ?? false }
    var editable: [FieldSchema] { rows.fields.filter { rows.sent.contains($0.name) } }

    public var body: some View {
        Section(say(texts, rows.title)) {
            if let problem = problems[rows.name] {
                Text(problem).foregroundStyle(.red)
            }
            ForEach(Array(state.loaded.enumerated()), id: \.offset) { _, row in
                VStack(alignment: .leading) {
                    ForEach(rows.fields, id: \.name) { field in
                        LabeledContent(say(texts, field.label), value: Rows.shown(row[field.name], texts))
                    }
                }
            }
            ForEach(Array(state.added.indices), id: \.self) { index in
                VStack(alignment: .leading) {
                    ForEach(editable, id: \.name) { field in
                        Field(
                            field: field,
                            value: Binding(get: { state.added[index][field.name] ?? "" }, set: { state.added[index][field.name] = $0 }),
                            problem: problems[Rows.rowKey(rows, index, field.name)],
                            texts: texts,
                            readOnly: Rules.locked(field, Fields(uniqueKeysWithValues: state.added[index].map { ($0.key, JSON.string($0.value)) }))
                        )
                    }
                    Button(say(texts, "screens.removeRow"), role: .destructive) { state.added.remove(at: index) }
                }
            }
            Button(say(texts, "screens.addRow")) { state.added.append(Rows.emptyRow(rows)) }
                .disabled(full)
        }
    }
}
